//--------------------------------------------------------------------------//
//! \desc Will read an NVRAM image from the specified source address into
//!       the RAM cache.

//! \assume -none-

//! \notes  -none-

//! \param  nvram_image_flash Addess of a valid NVRAM image.

//! \return \b void

//! \throws -none-
//--------------------------------------------------------------------------//

void nvram_image_cache_rd (UInt8 * const nvram_image_flash)
{
  memcpy (nvram_image_cache , nvram_image_flash , NVRAM_IMAGE_SIZE) ;
}

